import 'package:flutter/material.dart';import 'package:sehatak/core/services/child_service.dart';class ChildTipsScreen extends StatelessWidget{const ChildTipsScreen({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('نصائح صحة الطفل')),body:StreamBuilder(stream:ChildService().streamTips(limit:30),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(16),children:s.data!.map((d)=>Card(child:ExpansionTile(leading:const Icon(Icons.lightbulb_outline,color:Color(0xFF00BCD4)),title:Text(d.title),subtitle:Text(d.category),children:[Padding(padding:const EdgeInsets.all(16),child:Text(d.body))]))).toList());}));}}
